#!/usr/bin/env python3
"""Fetch raw order pages and customer records from the local order service.

Usage: recon_fetch.py orders|customers DATA_DIR

Raw responses are saved under DATA_DIR; every non-200 response is appended to
DATA_DIR/events.log. Anything the client does not recognise (an unparseable
rate-limit hint, repeated failures) stops the run so it can be inspected
instead of being guessed at.
"""
import json
import os
import socket
import sys
import time
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://localhost:8080"
MAX_TRANSIENT = 8   # failures of one request before stopping to look
MAX_REAUTH = 4      # 401s in a row on one request before stopping to look
MAX_WAIT = 120.0    # a rate-limit wait longer than this is treated as a mis-parse


class Stop(Exception):
    pass


def wait_hint(hdrs, body):
    """Seconds the service asked us to wait, or None if we cannot tell."""
    for k, v in hdrs.items():
        if k.lower() == "retry-after":
            try:
                return float(v)
            except ValueError:
                return None
    try:
        obj = json.loads(body)
    except ValueError:
        return None
    if isinstance(obj, dict):
        for k, v in obj.items():
            kl = k.lower()
            if ("retry" in kl or "wait" in kl) and isinstance(v, (int, float)):
                return float(v) / 1000.0 if "ms" in kl else float(v)
    return None


class Client:
    def __init__(self, data_dir):
        self.data_dir = data_dir
        self.log_path = os.path.join(data_dir, "events.log")
        self.token = None
        self.tokens_issued = 0
        self.requests = 0
        self.counts = {}

    def log(self, msg):
        with open(self.log_path, "a") as f:
            f.write("%s req#%d %s\n" % (time.strftime("%H:%M:%S"), self.requests, msg))

    def raw(self, method, path, auth):
        headers = {}
        if auth and self.token:
            headers["Authorization"] = "Bearer " + self.token
        data = b"" if method == "POST" else None
        req = urllib.request.Request(BASE + path, data=data, method=method, headers=headers)
        self.requests += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                code, hdrs, body = r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            code, hdrs, body = e.code, dict(e.headers), e.read()
        except (urllib.error.URLError, socket.timeout, ConnectionError) as e:
            code, hdrs, body = None, {}, repr(e).encode()
        self.counts[code] = self.counts.get(code, 0) + 1
        return code, hdrs, body

    def new_token(self):
        obj = self.call("POST", "/token", False,
                        lambda o: isinstance(o.get("token"), str) and o["token"] != "")
        self.token = obj["token"]
        self.tokens_issued += 1
        self.log("issued token %s" % self.token)

    def call(self, method, path, auth, validate, allow_404=False):
        """Repeat a request until it succeeds; returns the decoded JSON body,
        or None for a 404 that persisted over three attempts (allow_404 only)."""
        failures = 0
        reauth = 0
        notfound = 0
        while True:
            if auth and self.token is None:
                self.new_token()
            code, hdrs, body = self.raw(method, path, auth)
            if code == 200:
                try:
                    obj = json.loads(body)
                    ok = bool(validate(obj))
                except (ValueError, KeyError, TypeError, AttributeError):
                    obj, ok = None, False
                if ok:
                    return obj
                self.log("200 with unusable body for %s %s: %r" % (method, path, body[:300]))
                failures += 1
            elif code == 401 and auth:
                self.log("401 for %s (token %s): hdrs=%r body=%r" % (path, self.token, hdrs, body[:300]))
                self.token = None
                reauth += 1
                if reauth > MAX_REAUTH:
                    raise Stop("repeated 401 for %s" % path)
                continue
            elif code == 429:
                wait = wait_hint(hdrs, body)
                self.log("429 for %s: wait=%r hdrs=%r body=%r" % (path, wait, hdrs, body[:300]))
                if wait is None or wait < 0 or wait > MAX_WAIT:
                    raise Stop("unrecognised rate-limit response for %s: %r %r" % (path, hdrs, body[:300]))
                time.sleep(wait + 0.25)
                continue
            elif code == 404 and allow_404:
                notfound += 1
                self.log("404 for %s (attempt %d): body=%r" % (path, notfound, body[:300]))
                if notfound >= 3:
                    return None
            else:
                self.log("status %r for %s %s: hdrs=%r body=%r" % (code, method, path, hdrs, body[:300]))
                failures += 1
            if failures > MAX_TRANSIENT:
                raise Stop("too many failures for %s %s" % (method, path))
            time.sleep(min(0.5 * 2 ** max(failures - 1, 0), 8.0))


def page_ok(n):
    def check(o):
        return (isinstance(o, dict)
                and o.get("page") == n
                and isinstance(o.get("total_pages"), int)
                and isinstance(o.get("items"), list)
                and "next" in o)
    return check


def customer_ok(cid):
    def check(o):
        return (isinstance(o, dict) and o.get("id") == cid
                and all(k in o for k in ("name", "region", "tier", "discount_pct")))
    return check


def fetch_orders(c):
    pdir = os.path.join(c.data_dir, "pages")
    os.makedirs(pdir, exist_ok=True)
    path = "/orders?page=1"
    seen = []
    total = None
    while path is not None:
        q = urllib.parse.parse_qs(urllib.parse.urlparse(path).query)
        n = int(q["page"][0])
        if n in seen:
            raise Stop("next-link loop at page %d" % n)
        obj = c.call("GET", path, True, page_ok(n))
        with open(os.path.join(pdir, "page-%03d.json" % n), "w") as f:
            json.dump(obj, f)
        if total is None:
            total = obj["total_pages"]
        elif obj["total_pages"] != total:
            c.log("total_pages changed from %r to %r at page %d" % (total, obj["total_pages"], n))
        seen.append(n)
        print("page %d/%d: %d items, next=%r" % (n, obj["total_pages"], len(obj["items"]), obj["next"]))
        sys.stdout.flush()
        path = obj["next"]
    if seen != list(range(1, total + 1)):
        raise Stop("pages fetched %r do not cover 1..%r" % (seen, total))


def fetch_customers(c):
    ids = set()
    pdir = os.path.join(c.data_dir, "pages")
    for name in sorted(os.listdir(pdir)):
        with open(os.path.join(pdir, name)) as f:
            for item in json.load(f)["items"]:
                if item.get("status") == "shipped":
                    ids.add(item["customer_id"])
    out_path = os.path.join(c.data_dir, "customers.json")
    cust = {}
    if os.path.exists(out_path):
        with open(out_path) as f:
            cust = json.load(f)
    todo = sorted(i for i in ids if i not in cust)
    print("%d distinct customers on shipped orders, %d already cached, %d to fetch"
          % (len(ids), len(ids) - len(todo), len(todo)))
    for i, cid in enumerate(todo, 1):
        rec = c.call("GET", "/customers/" + urllib.parse.quote(cid, safe=""), True,
                     customer_ok(cid), allow_404=True)
        cust[cid] = rec if rec is not None else {"id": cid, "_missing": True}
        with open(out_path, "w") as f:
            json.dump(cust, f, sort_keys=True)
        if i % 20 == 0:
            print("  fetched %d/%d" % (i, len(todo)))
            sys.stdout.flush()


def main():
    mode, data_dir = sys.argv[1], sys.argv[2]
    c = Client(data_dir)
    try:
        if mode == "orders":
            fetch_orders(c)
        elif mode == "customers":
            fetch_customers(c)
        else:
            raise SystemExit("unknown mode %r" % mode)
    except Stop as e:
        print("STOPPED: %s" % e)
        print("requests=%d tokens_issued=%d status_counts=%r" % (c.requests, c.tokens_issued, c.counts))
        sys.exit(2)
    print("done: requests=%d tokens_issued=%d status_counts=%r" % (c.requests, c.tokens_issued, c.counts))


if __name__ == "__main__":
    main()

