            print("  fetched %d/%d" % (i, len(todo)))
            sys.stdout.flush()


def main():
    mode, data_dir = sys.argv[1], sys.argv[2]
    c = Client(data_dir)
    try:
        if mode == "orders":
            fetch_orders(c)
        elif mode == "customers":
            fetch_customers(c)
        else:
            raise SystemExit("unknown mode %r" % mode)
    except Stop as e:
        print("STOPPED: %s" % e)
        print("requests=%d tokens_issued=%d status_counts=%r" % (c.requests, c.tokens_issued, c.counts))
        sys.exit(2)
    print("done: requests=%d tokens_issued=%d status_counts=%r" % (c.requests, c.tokens_issued, c.counts))


if __name__ == "__main__":
